class Stack:
    def __init__(self):
        self.data = []

    def push(self, value):
        self.data.append(value)

    def pop(self):
        if self.is_empty():
            raise IndexError("empty stack")
        last = self.data[-1]
        del self.data[-1]
        return last

    def peek(self):
        if self.is_empty():
            raise IndexError("empty stack")
        return self.data[-1]

    def is_empty(self):
        return not self.data


def stack_ops(operations):
    stack = Stack()
    out = []
    for op in operations:
        try:
            if op[0] == "push":
                stack.push(op[1])
                out.append(None)
            elif op[0] == "pop":
                out.append(stack.pop())
            elif op[0] == "peek":
                out.append(stack.peek())
            else:
                out.append(stack.is_empty())
        except IndexError:
            out.append("IndexError")
    return out
